"""Persist the EEPROM generated by Xemu, without replacing an existing identity."""
import fcntl
import os
from pathlib import Path
import subprocess
import stat


def read_eeprom(path):
    path=Path(path)
    if path.is_symlink():raise ValueError('EEPROM não pode ser link simbólico')
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW)
    with os.fdopen(fd,'rb') as stream:
        if not stat.S_ISREG(os.fstat(stream.fileno()).st_mode):raise ValueError('EEPROM não é arquivo regular')
        data=stream.read(257)
    if len(data)!=256 or len(set(data))<2:raise ValueError('EEPROM inválida: esperado arquivo de 256 bytes')
    return data


def persist_initial(run=Path('/run/console'),console=Path('/console'),remount=None):
    run,console=Path(run),Path(console)
    source=run/'eeprom.bin';destination=console/'firmware/xbox/eeprom.bin'
    if not source.exists():return False
    # A creation event can precede fclose. The later close event retries safely.
    try:data=read_eeprom(source)
    except ValueError:return False
    lock_fd=os.open(run/'eeprom-save.lock',os.O_RDWR|os.O_CREAT|os.O_NOFOLLOW,0o600)
    with os.fdopen(lock_fd,'a') as lock:
        fcntl.flock(lock,fcntl.LOCK_EX)
        if destination.exists() or destination.is_symlink():return False
        if not destination.parent.resolve().is_relative_to(console.resolve()):raise ValueError('Destino de EEPROM inválido')
        if remount is None:
            def remount(mode):subprocess.run(['mount','-o','remount,'+mode,str(console)],check=True)
        temporary=destination.with_name('eeprom.bin.new')
        remount('rw')
        try:
            destination.parent.mkdir(parents=True,exist_ok=True)
            # Never follow a stale temporary path. FAT32 itself has no symlinks.
            fd=os.open(temporary,os.O_WRONLY|os.O_CREAT|os.O_TRUNC|os.O_NOFOLLOW,0o600)
            with os.fdopen(fd,'wb') as out:out.write(data);out.flush();os.fsync(out.fileno())
            if read_eeprom(temporary)!=data:raise ValueError('EEPROM gravada não confere')
            os.replace(temporary,destination)
            directory=os.open(destination.parent,os.O_RDONLY|os.O_DIRECTORY)
            try:os.fsync(directory)
            finally:os.close(directory)
        finally:remount('ro')
    print('eeprom: identidade gerada pelo Xemu preservada no SSD',flush=True)
    return True


if __name__=='__main__':persist_initial()
